const fs = require('fs');

const input = fs.readFileSync('/dev/stdin', 'utf8').trim();
const data = input.split(/\s+/).map(Number);
const n = data[0];

const stack = [];
let sum = 0;

for (let i = 1; i <= n; i++) {
  const x = data[i];
  if (x === 0) {
    if (stack.length > 0) {
      sum -= stack.pop();
    }
  } else {
    stack.push(x);
    sum += x;
  }
}

console.log(sum);
